-- Query to find total food consumption by food item across all events using CUBE
-- English version
-- Retrieve the name of each food item and the total quantity consumed from the tables Fall24_S003_T9_Consumes and Fall24_S003_T9_Food_item, while also including 
-- subtotals for each food item and the overall grand total.
SELECT 
    f.Food_name,
    SUM(fc.quantity) AS total_quantity_consumed
FROM 
    Fall24_S003_T9_Consumes fc
JOIN 
    Fall24_S003_T9_Food_item f ON fc.F_id = f.F_id
GROUP BY 
    CUBE(f.Food_name);

-- OUTPUT of this query
-- FOOD_NAME                                                                                            TOTAL_QUANTITY_CONSUMED                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
-- -- ---------------------------------------------------------------------------------------------------- -----------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
