-- -- 9 rows selected.



-- Query to find events with the most wasted food items
-- English version
-- Retrieve the name of each event and the food items that had leftovers, along with the total leftover quantity for each food item at each event, but only include 
-- results where the total leftover quantity exceeds 1.

SELECT 
    e.Ename AS event_name,
    f.Food_name,
    SUM(fl.L_quantity) AS total_leftover
FROM 
    Fall24_S003_T9_Event e
JOIN 
    Fall24_S003_T9_Produces p ON e.event_id = p.event_id
JOIN 
    Fall24_S003_T9_Food_Leftover fl ON p.leftover_id = fl.leftover_id
JOIN 
    Fall24_S003_T9_Food_item f ON fl.leftover_id = f.F_id
GROUP BY 
    e.Ename, f.Food_name
HAVING 
    SUM(fl.L_quantity) > 1;

-- OUTPUT of this query
