-- 20 rows selected.

   
-- Only show food items where more than 3 units were consumed 
-- English version
-- Retrieve the name of each event and the food items consumed during those events, along with the total quantity consumed for each food item, but only include results
--  where the total quantity consumed exceeds 3.
SELECT 
    e.Ename AS event_name,
    f.Food_name,
    SUM(c.quantity) AS total_quantity_consumed
FROM 
    Fall24_S003_T9_Event e
JOIN 
    Fall24_S003_T9_Attendance_Record ar ON e.event_id = ar.event_id
JOIN 
    Fall24_S003_T9_Consumes c ON ar.mav_id = c.mav_id
JOIN 
    Fall24_S003_T9_Food_item f ON c.F_id = f.F_id
GROUP BY 
    e.Ename, f.Food_name
HAVING 
    SUM(c.quantity) > 3;

-- OUTPUT of this query
