-- 46 rows selected.

-- Query to find popular food items containing 'Wrap'
-- English version
-- Retrieve the names of food items that contain 'Wrap' in their name and count how many times each of these items was consumed, listing the results in descending order
--  of frequency.
SELECT 
    f.Food_name,
    COUNT(*) AS frequency
FROM 
    Fall24_S003_T9_Consumes fc
JOIN 
    Fall24_S003_T9_Food_item f ON fc.F_id = f.F_id
WHERE 
    f.Food_name LIKE '%Wrap%'
GROUP BY 
    f.Food_name
ORDER BY 
    frequency DESC;
    
-- OUTPUT of this query
-- FOOD_NAME                                                                                             FREQUENCY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
