-- Query to generate report of most frequent attendees
-- English version
-- Retrieve the names of attendees and the events they attended, along with the total number of times each attendee participated in events. Additionally, include 
-- subtotals for each attendee and event, and a grand total of all attendance counts, sorted by attendance count in descending order.
SELECT 
    att.Fname || ' ' || att.Lname AS attendee_name,
    e.Ename AS event_name,
    COUNT(*) AS attendance_count
FROM 
    Fall24_S003_T9_Attendee att
JOIN 
    Fall24_S003_T9_Attendance_record ar ON att.mav_id = ar.mav_id
JOIN 
    Fall24_S003_T9_Event e ON ar.event_id = e.event_id
GROUP BY 
    ROLLUP(att.Fname || ' ' || att.Lname, e.Ename)
ORDER BY 
    attendance_count DESC;
    
-- OUTPUT of this query
-- ATTENDEE_NAME                                                                                         EVENT_NAME                                                                                           ATTENDANCE_COUNT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
