-- Karen Anderson                                                                                                                                                                                                            1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             

-- 197 rows selected.

-- Query to find food items consumed by all attendees
-- English version
-- Retrieve the names of food items that were consumed by every attendee.
SELECT 
    f.Food_name
FROM 
    Fall24_S003_T9_Food_item f
WHERE NOT EXISTS (
    SELECT a.mav_id
    FROM Fall24_S003_T9_Attendee a
    WHERE NOT EXISTS (
        SELECT fc.mav_id
        FROM Fall24_S003_T9_Consumes fc
        WHERE fc.F_id = f.F_id AND fc.mav_id = a.mav_id
    )
);

-- OUTPUT of this query
-- no rows selected

-- Query to generate report summary with top 5 highest leftovers, without Administrator
-- English version
-- Retrieve the IDs and dates of reports, along with the total quantity of leftover food associated with each report. Display the top 5 reports with the highest total 
-- leftovers, sorted in descending order by the total quantity of leftovers.
SELECT 
    r.R_id,
    r.Rdate AS report_date,
    SUM(fl.L_quantity) AS total_leftovers
FROM 
    Fall24_S003_T9_Report r
JOIN 
    Fall24_S003_T9_Produces p ON r.event_id = p.event_id
JOIN 
    Fall24_S003_T9_Food_Leftover fl ON p.leftover_id = fl.leftover_id
GROUP BY 
    r.R_id, r.Rdate
ORDER BY 
    total_leftovers DESC
FETCH FIRST 5 ROWS ONLY;

-- OUTPUT of this query
--       R_ID REPORT_DA TOTAL_LEFTOVERS                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
