--Total Quantity of Each Food Item Consumed by Dietary Preference with quantity > 20
-- English version
-- Retrieve the names of food items and the dietary preferences of attendees who consumed them, along with the total quantity consumed for each food item by dietary 
-- preference. Include only those food items and dietary preferences where the total quantity consumed exceeds 20.
SELECT 
    f.Food_name,
    att.dietary_pref,
    SUM(c.quantity) AS total_quantity_consumed
FROM 
    Fall24_S003_T9_Food_item f
JOIN 
    Fall24_S003_T9_Consumes c ON f.F_id = c.F_id
JOIN 
    Fall24_S003_T9_Attendee att ON c.mav_id = att.mav_id
GROUP BY 
    f.Food_name, att.dietary_pref
HAVING 
    SUM(c.quantity) > 20;
 
-- OUTPUT of this query
-- FOOD_NAME                                                                                            DIETARY_PREF                                                                                         TOTAL_QUANTITY_CONSUMED                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
-- ---------------------------------------------------------------------------------------------------- ---------------------------------------------------------------------------------------------------- -----------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
-- Grilled Fish                                                                                         Eggitarian                                                                                                                23                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       


--Count of Unique Attendees per Event (only shows events where the number of unique attendees exceeds 5)
-- English version
-- Retrieve the names of events and the number of unique attendees for each event. Include only those events that had more than 5 unique attendees.
SELECT 
    e.Ename AS event_name,
    COUNT(DISTINCT ar.mav_id) AS unique_attendees
FROM 
    Fall24_S003_T9_Event e
JOIN 
    Fall24_S003_T9_Attendance_record ar ON e.event_id = ar.event_id
GROUP BY 
    e.Ename
HAVING 
    COUNT(DISTINCT ar.mav_id) > 5;
    
-- OUTPUT of this query
