-- 9 rows selected.

--Query with OVER Clause: Display each individual consumption record along with the average quantity consumed for that specific food item.
-- English version
-- Retrieve the name of each food item, the quantity consumed in individual instances, and the average quantity consumed for that food item across all instances.
SELECT 
    f.Food_name,
    c.quantity,
    AVG(c.quantity) OVER (PARTITION BY f.Food_name) AS avg_quantity_per_food
FROM 
    Fall24_S003_T9_Consumes c
JOIN 
    Fall24_S003_T9_Food_item f ON c.F_id = f.F_id;

